"""FastAPI service for the Decision Regret Predictor ML API.

STATUS: Skeleton only. No trained model exists yet — this service does not
generate predictions and reports that honestly through its endpoints.
"""

from fastapi import FastAPI
from fastapi.responses import JSONResponse

app = FastAPI(
    title="Decision Regret Predictor — ML Service",
    description=(
        "Skeleton ML API. The model has not been trained yet, "
        "so no predictions are generated by this service."
    ),
    version="0.0.1",
)

MODEL_TRAINED = False


@app.get("/")
def root():
    """Service information."""
    return {
        "service": "decision-regret-predictor-ml",
        "status": "skeleton",
        "model_trained": MODEL_TRAINED,
        "message": "Structure only — the model is not implemented yet.",
    }


@app.get("/health")
def health():
    """Health check; explicitly reports that no model is trained."""
    return {
        "status": "ok",
        "model_trained": MODEL_TRAINED,
        "detail": "Service is reachable. No model is loaded and no predictions are available.",
    }


@app.post("/predict")
def predict():
    """Prediction endpoint placeholder — intentionally not functional yet."""
    return JSONResponse(
        status_code=501,
        content={
            "detail": "Prediction is not available: the model has not been trained yet.",
            "model_trained": MODEL_TRAINED,
        },
    )
